type Side = 'long' | 'short';
type QuoteSide = 'bid' | 'ask';
type Regime = 'RANGE' | 'TREND_UP' | 'TREND_DOWN';
type RobotState = 'MM_NORMAL' | 'MM_SKEW' | 'TREND_DEFENSIVE' | 'REBASE' | 'PAUSE';
type RebaseMode = 'emergency' | 'non_emergency' | 'all';

interface QuoteOrder {
    id: string;
    side: QuoteSide;
    level: number;
    price: number;
    quantity: number;
    createdAt: number;
    createdIteration?: number;
    referenceMid: number;
    reduceOnly: boolean;
    positionId?: string;
    reason?: string;
    takeTargetNetPercentOfAmountOverride?: number | null;
}

interface PendingEntryIntent {
    id: string;
    side: Side;
    level: number;
    quantity: number;
    reason: string;
    sourceQuoteId: string;
    createdAt: number;
    createdIteration: number;
    takeTargetNetPercentOfAmountOverride?: number | null;
}

interface Position {
    positionId: string;
    side: Side;
    quantity: number;
    entryPrice: number;
    takePrice: number;
    entryTime: number;
    initialMargin: number;
    borrowedAmount: number;
    leverage: number;
    makerFeeRate: number;
    takerFeeRate: number;
    makerSlippagePercent: number;
    takerSlippagePercent: number;
    openFeeRate: number;
    closeFeeRate: number;
    openSlippagePercent: number;
    closeSlippagePercent: number;
    openExecutionMode: 'maker' | 'taker' | 'market';
    closeExecutionMode: 'maker' | 'taker' | 'market';
    dailyInterestRate: number;
    fundingRatePer8h: number;
    fundingIntervalHours: number;
    fundingFeeMode: 'none' | 'signed' | 'absolute_cost';
    maintenanceMarginRate: number;
    qgHedge: boolean;
    qgParentSide: Side;
    qgOpenReason: string;
    entryRegime?: string;
    entryOperationalRegime?: string;
    sourceQuoteId: string;
    takeTargetNetPercentOfAmountOverride?: number | null;
}

interface PositionExecutionCosts {
    openFeeRate?: number;
    closeFeeRate?: number;
    openSlippagePercent?: number;
    closeSlippagePercent?: number;
}

